"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Stack:
    def __init__(self, capacity):
        self.arr = [None] * capacity
        self.top_index = (-1)

    def Push(self, item):
        if (self.top_index == (len(self.arr) - 1)):
            return 'Overflow Error'
        self.top_index = (self.top_index + 1)
        self.arr[self.top_index] = item

    def Pop(self):
        if (self.top_index == (-1)):
            return 'Underflow Error'
        item = self.arr[self.top_index]
        self.top_index = (self.top_index - 1)
        return item

    def Peek(self):
        if (self.top_index == (-1)):
            return 'Stack Empty'
        return self.arr[self.top_index]
